$_ADMINLANG['marketConnect']['socialbee']['about']['author'] = "- Ovi Negrean，SocialBee 執行長";
$_ADMINLANG['marketConnect']['socialbee']['about']['p1'] = "SocialBee 是一套整合式社群媒體管理工具，讓使用者能在同一處將內容分享到多個社群平台。您可以設定發文排程、分享內容、分析成效，並與追蹤者互動。";
$_ADMINLANG['marketConnect']['socialbee']['about']['p2'] = "SocialBee 創立的目標是簡化各種規模企業的社群媒體管理。自 2016 年推出以來，這個平台已發展成完整工具，讓使用者能在同一處建立、排程、分析內容，並在各個平台上互動。SocialBee 著重易用設計與分類排程、分析等強大功能，深受企業家、行銷人員與代理商信賴，可協助他們經營社群媒體並與受眾建立有意義的連結。";
$_ADMINLANG['marketConnect']['socialbee']['about']['quote'] = "\"在 SocialBee，我們的使命是協助企業在社群媒體上取得成功，無須費心切換多種工具。我們深受全球數千名使用者信賴，結合強大功能與以客戶為先的服務，確保您順利達成目標。無論您才剛起步，或是正在管理大量社群媒體帳戶，SocialBee 都會一路協助您。\"";
$_ADMINLANG['marketConnect']['socialbee']['about']['title'] = "關於我們";
$_ADMINLANG['marketConnect']['socialbee']['faq']['h1'] = "SocialBee 可管理哪些社群媒體平台？";
$_ADMINLANG['marketConnect']['socialbee']['faq']['h2'] = "SocialBee 使用者可使用哪些支援方式？";
$_ADMINLANG['marketConnect']['socialbee']['faq']['h3'] = "SocialBee 代理商方案與一般 Pro 方案有何不同？";
$_ADMINLANG['marketConnect']['socialbee']['faq']['h4'] = "SocialBee 的伺服器位於何處？資料儲存在哪裡？";
$_ADMINLANG['marketConnect']['socialbee']['faq']['h5'] = "為什麼要銷售社群媒體管理工具？";
$_ADMINLANG['marketConnect']['socialbee']['faq']['h6'] = "企業會付費使用社群媒體工具嗎？";
$_ADMINLANG['marketConnect']['socialbee']['faq']['q1'] = "您可以管理並排程 Facebook、Instagram、Threads、X™（前稱 Twitter™）、LinkedIn、Pinterest、Google 商家檔案™、TikTok、YouTube™ 和 Bluesky 等熱門平台的內容。";
$_ADMINLANG['marketConnect']['socialbee']['faq']['q2'] = "使用者可以透過即時聊天、<a href=\"mailto:hello@socialbee.com\">電子郵件</a>、<a href=\"https://socialbee.com/calendar\">通話</a>，以及提供豐富實用資源的<a href=\"https://help.socialbee.com\">知識庫</a>，取得 SocialBee 的協助。";
$_ADMINLANG['marketConnect']['socialbee']['faq']['q3'] = "代理商方案（Pro50、Pro100 和 Pro150）與 Pro 方案具備相同功能。主要差異在於可連結的社群媒體個人檔案數量、工作區數量，以及可新增至工作區的使用者人數：";
$_ADMINLANG['marketConnect']['socialbee']['faq']['q4'] = "SocialBee 的伺服器位於歐洲愛爾蘭。";
$_ADMINLANG['marketConnect']['socialbee']['faq']['q5'] = "銷售 SocialBee 這類社群媒體管理工具，可掌握市場對社群媒體行銷解決方案日益增加的需求。中小型企業需要工具來管理社群媒體個人檔案、節省時間並提高互動率，因此為您這類轉售商創造了可觀的服務市場。";
$_ADMINLANG['marketConnect']['socialbee']['faq']['q6'] = "是的，中小型企業正快速投資社群媒體工具，以管理其社群媒體經營。社群媒體是最常使用的行銷管道之一，有助於企業成長，因此企業樂於投資可靠工具，協助自己達成目標。";
$_ADMINLANG['marketConnect']['socialbee']['features']['f1']['p1'] = "SocialBee 整合 Canva、Unsplash 和 GIPHY，讓您輕鬆為貼文建立並整理視覺素材。";
$_ADMINLANG['marketConnect']['socialbee']['features']['f1']['p2'] = "透過 AI 在幾秒內產生說明文字與圖片，並取得 1,000 多個預先製作的提示詞，節省時間。";
$_ADMINLANG['marketConnect']['socialbee']['features']['f1']['p3'] = "嘗試圖片、影片、輪播、限時動態和 Reels 等不同貼文類型，找出最能引起受眾共鳴的形式。";
