$_ADMINLANG['marketConnect']['threesixtymonitoring']['about']['asterisk'] = "以網站年營收 $500K 為例，不包含行銷活動旺季。";
$_ADMINLANG['marketConnect']['threesixtymonitoring']['about']['p1'] = "WebPros 旗下品牌服務超過 3,300 萬名使用者與 8,500 萬個網域。提供 360 Monitoring，即可運用業界領導者的專業知識！";
$_ADMINLANG['marketConnect']['threesixtymonitoring']['about']['p2'] = "360 Monitoring 提供領先業界的內外部系統監控，具備可設定的儀表板、個人化警示，並可順暢整合主流資料庫與伺服器技術。此服務由 cPanel®、Plesk® 和 WHMCS 等知名品牌支援，是市場上最完整的監控解決方案。";
$_ADMINLANG['marketConnect']['threesixtymonitoring']['about']['p3'] = "正常運作時間就是客戶的收益：即使網站正常運作率達 98%，年營收 $500k 的網站仍可能因停機每年損失 $10,000*！透過 360 Monitoring，客戶可確保訪客享有最佳效能、避免代價高昂的停機，並主動處理可能影響業務的問題。";
$_ADMINLANG['marketConnect']['threesixtymonitoring']['about']['subtitle'] = "WebPros 網站與伺服器監控";
