$_ADMINLANG['marketConnect']['threesixtymonitoring']['faq']['a1a'] = "網站監控服務會依固定間隔（視方案而定，每 1、5 或 10 分鐘）自動測試網站。這些測試可偵測客戶網站目前及潛在的問題。發現問題時，360 Monitoring 會發出警示並記錄問題，供日後分析。";
$_ADMINLANG['marketConnect']['threesixtymonitoring']['faq']['a1b']['i1'] = "服務停機";
