$_ADMINLANG['marketConnect']['threesixtymonitoring']['faq']['a1b']['p1'] = "網站監控涵蓋以下項目：";
$_ADMINLANG['marketConnect']['threesixtymonitoring']['faq']['a2a'] = "其中一個監控探測點偵測到停機時，360 Monitoring 會立即從另外五個位置確認狀況，避免發出誤報。";
$_ADMINLANG['marketConnect']['threesixtymonitoring']['faq']['a3a'] = "效能監控工具與程序會監測 CPU 使用率、記憶體用量、磁碟使用量、輸入／輸出（I/O）效能及網路正常運作時間等系統資源，檢查系統運作狀況。360 Monitoring 會追蹤所有這些指標，確保系統如預期正常運作。";
$_ADMINLANG['marketConnect']['threesixtymonitoring']['faq']['a4a'] = "效能監控對於在效能問題影響終端使用者體驗前及早發現問題至關重要。系統資源分析結果也能讓客戶主動規劃伺服器未來的容量需求，包括向您購買更多主機代管服務！";
$_ADMINLANG['marketConnect']['threesixtymonitoring']['faq']['a5a'] = "透過 SSL 監控，客戶可以輕鬆追蹤 SSL 憑證並預先規劃憑證到期時間，全面簡化憑證管理。";
$_ADMINLANG['marketConnect']['threesixtymonitoring']['faq']['a6a'] = "您的客戶可以從世界各地監控網站或伺服器，監控據點包括澳洲、加拿大、芬蘭、法國、德國、日本、墨西哥、荷蘭、瑞典、英國及美國。";
$_ADMINLANG['marketConnect']['threesixtymonitoring']['faq']['a7a'] = "360 Monitoring 支援英文、德文、日文、西班牙文、義大利文、巴西葡萄牙文、法文及俄文。";
