$_ADMINLANG['marketConnect']['xoviNow']['about']['h1'] = "XOVI NOW";
$_ADMINLANG['marketConnect']['xoviNow']['about']['h2'] = "關於 XOVI NOW（產品歷程）";
$_ADMINLANG['marketConnect']['xoviNow']['about']['p1'] = "企業需要專業知識與合適的 SEO 工具，才能讓網站登上 Google® 搜尋結果的前列。若沒有關鍵字研究、網站分析和競爭者情報，就難以提升產品與服務的能見度。";
$_ADMINLANG['marketConnect']['xoviNow']['about']['p2'] = "中小型企業可藉由合適的 SEO 工具輕鬆完成這些工作，進而建立高品質內容，推動並支援企業網站的搜尋引擎最佳化。";
$_ADMINLANG['marketConnect']['xoviNow']['about']['p3'] = "XOVI NOW 專為中小型企業打造。身為 SEO 專家，我們曾與許多企業主交流，評估眾多企業網站的優缺點，並運用自身 SEO 專業知識設計出一項產品，讓每個人都能輕鬆掌握 SEO 的複雜之處。";
$_ADMINLANG['marketConnect']['xoviNow']['about']['p4'] = "XOVI NOW 協助中小型企業找出相關關鍵字、最佳化現有內容並撰寫新部落格文章，無須聘請 SEO 專家或超出預算。";
$_ADMINLANG['marketConnect']['xoviNow']['about']['p5'] = "客戶選擇 XOVI NOW，也就選擇了順暢的導入體驗與逐步指引，幫助他們隨著時間逐漸提升能見度。";
$_ADMINLANG['marketConnect']['xoviNow']['about']['p6'] = "XOVI NOW 是 WebPros Extension 系列的最新成員，於 2022 年 2 月推出，提供先進的關鍵字、排名追蹤與競爭者分析工具。XOVI 是 WebPros 旗下公司，在 SEO 產業深耕超過 13 年，是知名品牌，也是搜尋引擎最佳化 SaaS 領域的領先開發商。";
$_ADMINLANG['marketConnect']['xoviNow']['about']['p7'] = "WebPros 提供創新技術，推動數位世界發展。我們整合各項產品與解決方案，協助企業在線上建立、營運並成長。我們的產品可協助管理伺服器、網站、帳務與網路行銷。WebPros 有專責 SEO 專家團隊參與打造 XOVI NOW，並投入數月研究，找出適合中小型企業與 SEO 初學者的解決方案。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a1a'] = "既有 SEO 產品為 SEO 專家和熟悉技術的使用者提供大量功能；XOVI NOW 則希望成為搜尋引擎最佳化產業中的網站建置工具，讓 SEO 更容易上手。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a1b'] = "XOVI NOW 簡單易用，提供指引與合適的功能，讓客戶能逐步成長。中小型企業對價格較為敏感，因此 XOVI NOW 提供極具競爭力的價格，同時維持產品品質。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a2a'] = "XOVI NOW 是 SaaS 解決方案。使用 XOVI NOW 不需要其他 WebPros 產品或擴充功能，也不需要自行準備伺服器。XOVI NOW 可獨立運作，適用於全球任何地方託管的網站。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a2b'] = "這也表示您只要登入帳戶，就能透過任何電腦和瀏覽器存取 XOVI NOW。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a3a'] = "每位網站擁有者都知道，要在網路上提升能見度並不容易。XOVI NOW 提供適當功能來提高網站能見度。您可以搜尋我們資料庫中的商業相關關鍵字、每週或每日追蹤排名（視方案等級而定）、最佳化現有或新內容，並檢查網站是否有妨礙 Google® 排名提升的技術問題。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a4a'] = "我們全力支援轉售商並提供協助。您的客戶應先聯絡您；如果您無法提供滿意的答覆，我們會全力協助您，盡快解決問題。只要透過 <a href=\"https://support.xovinow.com/\" class=\"autoLinked\">XOVI NOW 客服單系統</a>聯絡我們，客服人員就會樂意提供協助。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a5a'] = "專案是以特定 URL（通常是客戶的網站）為基礎，並會自動建立網站檢查（掃描網站以找出技術問題）。客戶只要依照導入精靈的步驟操作，即可設定專案。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a6a'] = "完整存取帳戶在 XOVI NOW 產品中具有完整管理權限。您可以依需求變更、編輯或新增任何項目（例如關鍵字、專案或工作）。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a6b'] = "唯讀帳戶可存取 XOVI NOW 並檢視產品提供的所有 SEO 資訊，但無法編輯專案中的任何內容。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a7a'] = "網站檢查會掃描網站的技術架構，為提升 Google® 與其他搜尋引擎的排名奠定基礎。每個專案最多可分析 10k 個頁面／URL（XOVI NOW Starter 方案每個專案可分析 500 個頁面）。掃描結果會自動加入產品內的 Advisor 工具，並針對每個問題建立明確的工作項目。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a7b'] = "專案掃描所需時間取決於頁面／URL 數量。較小的網站只需幾分鐘；較大的線上商店則可能需要數小時才能完成分析。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a8a'] = "此產品主要為 SEO 初學者設計，適合沒有或只有少量搜尋引擎最佳化知識的使用者。如前所述，XOVI NOW 專為中小型企業打造，在此目標族群中獲得非常正面的測試結果。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a8b'] = "Pro 等級也提供非常適合小型代理商的方案。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a8c'] = "XOVI NOW 具備豐富功能與超過 100M 個關鍵字的資料庫，也非常適合進階 SEO 使用者。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a9a'] = "比較 XOVI NOW 與 SEMrush 就像拿蘋果和橘子相比，兩者各有特色。SEMrush 面向專業 SEO 行銷人員，累積超過 12 年經驗，並針對不同需求提供各種產品，因此不能稱為一體適用的工具。其使用體驗是為進階使用者打造，功能對 SEO 初學者來說也過於繁多。";
$_ADMINLANG['marketConnect']['xoviNow']['faq']['a9b'] = "SEMrush 適合 SEO 專家與經驗豐富的行銷經理；XOVI NOW 則更適合初學者和需要更多成功指引的使用者。既有產品沒有導入精靈與 SEO Advisor 等功能。如果您的客戶需要適合中小型企業的產品，XOVI NOW 就是理想選擇。";
