$_ADMINLANG['supportticketdepts']['pop3oauthsetupinstructions']['Google'] = "<h1>Google OAuth 設定指南</h1><p>1. 登入 <a href=\"https://console.developers.google.com/\" target=\"_blank\">Google Developer Console</a>。</p><p>2. 選擇現有專案或建立新專案。</p><p>3. 使用提供的 <i>Redirect URI</i> 建立 OAuth 憑證。</p><p>4. 將產生的 <strong>Client ID/Secret</strong> 輸入指定欄位。</p><p>5. 按一下 <strong>&quot;Connect&quot;</strong> 以產生連線權杖。</p><p>6. 按一下 <strong>&quot;Test Configuration&quot;</strong> 以驗證設定。</p>";
$_ADMINLANG['supportticketdepts']['pop3oauthsetupinstructions']['Microsoft'] = "<h1>Microsoft® OAuth 設定指南</h1><p>1. 登入 <a href=\"https://portal.azure.com/\" target=\"_blank\">Microsoft Azure® 主控台</a>。</p><p>2. 選擇 <strong>Azure Active Directory</strong>。</p><p>3. 使用顯示的 <strong>Redirect URI</strong> 建立新的應用程式註冊。</p><p>4. 輸入產生的 <strong>Client ID</strong> 與 <strong>Client Secret</strong>。</p><p>5. 按一下 <strong>Connect</strong> 以產生連線權杖。</p><p>6. 按一下 <strong>&quot;Test Configuration&quot;</strong> 以驗證設定。</p>";
